WITH scored AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY quantity NULLS FIRST) quantity_percent_rank, AVG(quantity) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) quantity_avg_5 FROM inventory) SELECT CASE WHEN quantity_avg_5 >= 235 THEN 'HIGH' ELSE 'LOW' END AS quantity_avg_5_tier, CASE WHEN quantity_percent_rank >= 0.84 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_percent_rank_tier, STDDEV_SAMP(quantity) AS quantity_stddev, PERCENTILE_APPROX(quantity_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS quantity_percent_rank_quartiles, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, PERCENTILE_APPROX(quantity_avg_5, ARRAY(0.25, 0.5, 0.75)) AS quantity_avg_5_quartiles, COUNT(*) AS row_count, COUNT(DISTINCT store_id) AS distinct_store_ids, RANK() OVER (PARTITION BY CASE WHEN quantity_avg_5 >= 235 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) DESC) AS row_count_rank FROM scored GROUP BY quantity_avg_5_tier, quantity_percent_rank_tier ORDER BY distinct_store_ids DESC
